// OpenAI response'u parse et
const webhookData = $('Webhook').first().json;
const openaiResponse = $json;

// AI response'u al
const aiMessage = openaiResponse.choices[0].message.content;

console.log('=== DEBUG ===');
console.log('AI Response:', aiMessage);
console.log('=============');

// TAG'leri bul
const hasImageTag = aiMessage.includes('[IMAGE:');
const hasCatalogTag = aiMessage.includes('[CATALOG]');
const hasPricelistTag = aiMessage.includes('[PRICELIST]');
const hasSalesTag = aiMessage.includes('[SALES]');

// Ürün adını çıkar (eğer IMAGE tag varsa)
let productName = 'Chair';
if (hasImageTag) {
  const match = aiMessage.match(/\[IMAGE:([^\]]+)\]/);
  if (match) {
    productName = match[1].trim();
  }
}

// Müşteriye gönderilecek temiz mesaj
const cleanMessage = aiMessage
  .replace(/\[IMAGE:[^\]]+\]/g, '')
  .replace(/\[CATALOG\]/g, '')
  .replace(/\[PRICELIST\]/g, '')
  .replace(/\[SALES\]/g, '')
  .trim();

return {
  json: {
    recipient: webhookData.body.data.key.remoteJid,
    customerMessage: cleanMessage,
    hasImageTag: hasImageTag,
    hasCatalogTag: hasCatalogTag,
    hasPricelistTag: hasPricelistTag,
    hasSalesTag: hasSalesTag,
    productName: productName,
    fullAiResponse: aiMessage
  }
};

const productName = $json.productName;
